template<typename T, size_t N>
struct FixedSizeArray { T storage[N]; };

// The size N is known at template instantiation time.
template<typename T, size_t N>
bool compare(const FixedSizeArray<T, N>& a,
             const FixedSizeArray<T, N>& b) {
    // std::array::operator== uses compile-time N.
    // For small N (e.g., N=4, N=8), the compiler:
    // 1. Fully unrolls the loop.
    // 2. Uses single wide register instructions (SIMD/SSE/AVX)
    //    to compare large chunks (e.g., 16 or 32 bytes) at once.

    // Result: No runtime loop overhead needed for small arrays.
    return std::memcmp(a.storage, b.storage, N * sizeof(T)) == 0;
}
// This mechanism ensures specific assembly paths (polymorphism)
// for every unique size N.
